package com.practiq.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.practiq.common.ApiException; import java.io.*; import java.nio.file.*; import java.sql.ResultSet; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service public class ImportService {final JdbcTemplate db;final ObjectMapper json;final String mount,oss;public ImportService(JdbcTemplate d,ObjectMapper j,@Value("${practiq.object-storage-mount-dir}")String m,@Value("${OSS_PUBLIC_BASE_URL:}")String base,@Value("${OSS_URL_PREFIX:oss://practiq}")String prefix){db=d;json=j;mount=m;oss=base.isBlank()?prefix:base;}
 private Map<String,Object> row(ResultSet r,int n)throws java.sql.SQLException{var x=new LinkedHashMap<String,Object>();var m=r.getMetaData();for(int i=1;i<=m.getColumnCount();i++)x.put(m.getColumnLabel(i),r.getObject(i));x.remove("error_payload");return x;}private String js(Object x){try{return json.writeValueAsString(x==null?Map.of():x);}catch(JsonProcessingException e){throw ApiException.of(400,"INVALID_FILE_CONTENT","Invalid JSON content");}}private void pro(Map<String,Object> u){String m=String.valueOf(u.get("effectiveMembership"));if(!"pro".equals(m)&&!"organization".equals(m))throw ApiException.of(403,"PRO_MEMBERSHIP_REQUIRED","AI document imports requires Pro membership");}public Map<String,Object> job(long u,long id){var x=db.query("select * from question_import_jobs where id=? and created_by=?",this::row,id,u);if(x.isEmpty())throw ApiException.of(404,"NOT_FOUND","Import job not found");return x.getFirst();}private String source(String x){String s=x==null?"txt":x.trim().toLowerCase();return switch(s){case "","text","txt"->"txt";case "md","csv","docx","pdf","xlsx","image"->s;default->throw ApiException.of(400,"UNSUPPORTED_SOURCE_TYPE","Only txt, md, csv, docx, pdf, xlsx, and image imports are supported");};}
 public Map<String,Object> create(long u,Map<String,Object> me,Long bank,String file,String type,Map<String,Object> request){pro(me);if(bank!=null&&db.queryForObject("select count(*) from user_bank_links where user_id=? and bank_id=? and is_owner",Integer.class,u,bank)==0)throw ApiException.of(403,"FORBIDDEN","Question bank owner access required");return db.query("insert into question_import_jobs(created_by,bank_id,file_name,source_type,request_payload) values(?,?,?,?,?::text) returning *",this::row,u,bank,file,source(type),js(request)).getFirst();}
 public Map<String,Object> list(long u,String status,String cursor,Integer requested){Set<String> allowed=Set.of("queued","processing","completed","failed","cancelled");var ss=status==null?List.<String>of():Arrays.stream(status.split(",")).filter(x->!x.isBlank()).map(String::trim).toList();if(!allowed.containsAll(ss))throw ApiException.of(422,"VALIDATION_ERROR","Invalid request");int limit=requested==null?30:requested;if(limit<1||limit>100)throw ApiException.of(422,"VALIDATION_ERROR","Invalid request");int off=com.practiq.common.PageSupport.cursor(cursor);var x=db.query("select * from question_import_jobs where created_by=? and (?='' or status=any(string_to_array(?,','))) order by created_at desc limit ? offset ?",this::row,u,String.join(",",ss),String.join(",",ss),limit+1,off);boolean more=x.size()>limit;if(more)x=x.subList(0,limit);return Map.of("items",x,"meta",Map.of("pagination",Map.of("cursor",more?com.practiq.common.PageSupport.next(off,limit):"","limit",limit,"hasMore",more)));}
 @Transactional public Map<String,Object> upload(long u,Map<String,Object> me,long id,MultipartFile f){pro(me);job(u,id);if(f==null)throw ApiException.of(400,"FILE_REQUIRED","Upload file is required");byte[] b;try{b=f.getBytes();}catch(IOException e){throw ApiException.of(400,"INVALID_FILE_CONTENT","Could not read upload");}String n=Optional.ofNullable(f.getOriginalFilename()).orElse("");if(n.isBlank()||n.length()>255)throw ApiException.of(400,"INVALID_FILE_NAME","Upload file name is invalid");String ext=UploadSupport.extension(n,f.getContentType());UploadSupport.validateImport(ext,f.getContentType(),b,n);String rel="imports/"+u+"/"+id+"/source-"+System.currentTimeMillis()+"-"+UploadSupport.token()+ext;Path p=UploadSupport.path(mount,rel);try{Files.createDirectories(p.getParent());Files.write(p,b,StandardOpenOption.CREATE_NEW);}catch(IOException e){throw ApiException.of(500,"IMPORT_STORAGE_FAILED","Could not store import source");}try{String kind=UploadSupport.sourceType(ext);var content=new LinkedHashMap<String,Object>();content.put("objectUrl",oss.replaceAll("/$","")+"/"+rel);content.put("objectKey",rel);content.put("originalName",n);content.put("mimeType",Optional.ofNullable(f.getContentType()).orElse(""));content.put("sizeBytes",b.length);content.put("sourceType",kind);if(Set.of("txt","md","csv").contains(kind))content.put("text",new String(b,java.nio.charset.StandardCharsets.UTF_8));else content.put("fileBase64",Base64.getEncoder().encodeToString(b));var a=db.query("insert into question_import_job_artifacts(job_id,artifact_type,storage_path,content_json) values(?,?,?,?::text) on conflict(job_id) where artifact_type='source_file' do nothing returning *",this::row,id,"source_file",content.get("objectUrl"),js(content));if(a.isEmpty())throw ApiException.of(409,"IMPORT_SOURCE_EXISTS","Import job already has a source file");db.update("update question_import_jobs set source_type=?,file_name=coalesce(file_name,?) where id=?",kind,n,id);return a.getFirst();}catch(RuntimeException e){try{Files.deleteIfExists(p);}catch(IOException ignored){}throw e;}}
 @Transactional public Map<String,Object> legacy(long u,Map<String,Object> me,long id,Map<String,Object> b){pro(me);var j=job(u,id);String artifact=String.valueOf(b.getOrDefault("artifactType","source_file"));if(!"source_file".equals(artifact))throw ApiException.of(422,"VALIDATION_ERROR","Invalid request");Object c=b.get("content");if(!(c instanceof Map<?,?>))throw ApiException.of(400,"SOURCE_FILE_REQUIRED","Import artifact requires storagePath or content");@SuppressWarnings("unchecked") Map<String,Object> content=(Map<String,Object>)c;String type=source(String.valueOf(b.getOrDefault("sourceType",content.getOrDefault("sourceType",j.get("source_type")))));validateLegacy(type,content);content.put("sourceType",type);String path=(String)b.get("storagePath");var x=db.query("insert into question_import_job_artifacts(job_id,artifact_type,storage_path,content_json) values(?,?,?,?::text) on conflict(job_id) where artifact_type='source_file' do nothing returning *",this::row,id,artifact,path,js(content));if(x.isEmpty())throw ApiException.of(409,"IMPORT_SOURCE_EXISTS","Import job already has a source file");db.update("update question_import_jobs set source_type=? where id=?",type,id);return x.getFirst();}
 private void validateLegacy(String type,Map<String,Object> c){try{if(Set.of("txt","md","csv").contains(type)){Object v=c.get("text");if(!(v instanceof String s))throw ApiException.of(400,"FILE_REQUIRED",type.toUpperCase()+" artifacts require text or fileBase64");UploadSupport.validateImport("."+type,"",s.getBytes(java.nio.charset.StandardCharsets.UTF_8),"source."+type);}else {Object v=c.get("fileBase64");if(!(v instanceof String s))throw ApiException.of(400,"FILE_REQUIRED",type.toUpperCase()+" artifacts require fileBase64");byte[] z=Base64.getDecoder().decode(s);String ext=type.equals("image")?".png":"."+type;UploadSupport.validateImport(ext,String.valueOf(c.getOrDefault("mimeType","")),z,"source"+ext);}}catch(IllegalArgumentException e){throw ApiException.of(400,"INVALID_FILE_CONTENT","fileBase64 must contain valid base64");}}
 @Transactional public Map<String,Object> action(long u,Map<String,Object> me,long id,String action,Boolean persist){pro(me);var j=job(u,id);String status=String.valueOf(j.get("status")),stage=String.valueOf(j.get("stage"));if("completed".equals(status))throw ApiException.of(409,"IMPORT_ALREADY_COMPLETED","Completed import jobs cannot be queued again");if("cancel".equals(action)){if(!Set.of("queued","processing").contains(status)||"persisting".equals(stage))throw ApiException.of(409,"IMPORT_CANCEL_NOT_ALLOWED","Import job cannot be cancelled");return transition(id,status,"cancelled","cancelled","cancel","cancelled","任务已取消。",false,null);}if(!Set.of("parse","retry").contains(action))throw ApiException.of(400,"INVALID_IMPORT_ACTION","Unsupported import action");if("retry".equals(action)&&!"failed".equals(status))throw ApiException.of(409,"IMPORT_RETRY_NOT_ALLOWED","Only failed import jobs can be retried");if(db.queryForObject("select count(*) from question_import_job_artifacts where job_id=? and artifact_type='source_file'",Integer.class,id)==0)throw ApiException.of(409,"SOURCE_FILE_REQUIRED","Import job requires an uploaded source file before parsing");if("processing".equals(status)||("queued".equals(status)&&j.get("available_at")!=null))return j;return transition(id,status,"queued","queued",action.equals("retry")?"retry":"queue_parse","queued",null,true,persist==null?true:persist);}
 private Map<String,Object> transition(long id,String old,String status,String stage,String code,String event,String msg,boolean available,Boolean persist){var x=db.query("update question_import_jobs set status=?,stage=?,available_at=case when ? then now() else null end,completed_at=case when ?='cancelled' then now() else null end,persist_questions=coalesce(?,persist_questions),retry_count=case when ? then 0 else retry_count end,last_error_code=case when ?='cancelled' then 'IMPORT_CANCELLED' else null end,last_error=? where id=? and status=? returning *",this::row,status,stage,available,status,persist,available,status,msg,id,old);if(x.isEmpty())throw ApiException.of(409,"IMPORT_STATE_CHANGED","Import job state changed; refresh and try again");db.update("insert into question_import_job_events(job_id,stage,step_code,step_label,status,message,overall_progress_percent) values(?,?,?,?,?,?,?)",id,stage,code,code,event,msg,available?0:null);return x.getFirst();}
 public List<Map<String,Object>> children(long u,long id,String kind){job(u,id);String table=switch(kind){case "events"->"question_import_job_events";case "artifacts"->"question_import_job_artifacts";case "outputs"->"question_import_job_outputs";default->throw ApiException.of(400,"INVALID_IMPORT_CHILD_KIND","Unsupported import child kind");};return db.query("select * from "+table+" where job_id=? order by id"+(kind.equals("events")?" desc":"")+" limit "+(kind.equals("outputs")?200:100),this::row,id);}public boolean event(long id,long event){return db.queryForObject("select count(*) from question_import_job_events where job_id=? and id=?",Integer.class,id,event)>0;}public List<Map<String,Object>> eventsAfter(long id,long after){return db.query("select * from question_import_job_events where job_id=? and id>? order by id limit 100",this::row,id,after);}
}
